window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0d15c4f13ed62352"]={"versions": [{"id": "FIG-0d15c4f13ed62352", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0- / UML-Aktivitätendiagramm zur Darstellung des methodischen Workflows für die Bereitstellung und Verwaltung von Software-Paketen im Kontext der AUTOSAR Adaptive Platform Methodology. Es veranschaulicht die organisatorische Einbettung von Rollen, Eingangs- und Ausgangs-Arbeitsergebnissen sowie die hierarchische Zerlegung von Aufgaben im Lebenszyklus der Software-Paketierung für Backend-Systeme.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen & Akteure</strong>:</li>\n<li><code>OEM</code>: Agierender Akteur, der über die Relation <code>«performs»</code> mit der spezifischen Performer-Rolle <code>+ECU Software Manager</code> die Aktivität ausführt.</li>\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Provide and manage Software Packages</code>: Übergeordnete Aktivität (Zentralaufgabe).</li>\n<li><code>Management of Software Packages</code>: Verschachtelte Unteraktivität, über eine gerichtete Assoziation mit dem Stereotyp <code>«nesting»</code> (Komposition/Aggregation) angebunden.</li>\n<li><code>Provision of Software Packages for</code>: Verschachtelte Unteraktivität, ebenfalls über <code>«nesting»</code> angebunden (Beschriftung am Rand unvollständig).</li>\n<li><strong>Arbeitsergebnisse (Work Products / Artefakte)</strong>:</li>\n<li><code>Software Package</code>: Eingangsartefakt (Stereotyp <code>«input»</code>, Kardinalität <code>1..*</code>).</li>\n<li><code>Back-end Server</code>: Ziel-/Ausgangskontext bzw. Artefakt für die Verteilung (Stereotyp <code>«output»</code>, Kardinalität <code>1..*</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Rolle <code>OEM</code> agiert als <code>+ECU Software Manager</code> und führt die Gesamtaktivität <code>Provide and manage Software Packages</code> durch (<code>«performs»</code>).</li>\n<li>Als Eingabe (<code>«input»</code>) fließen mindestens ein oder mehrere <code>Software Package</code>-Artefakte (<code>1..*</code>) in den Prozess ein.</li>\n<li>Die Gesamtaktivität untergliedert sich hierarchisch (<code>«nesting»</code>) in die beiden Teilaktivitäten <code>Management of Software Packages</code> und <code>Provision of Software Packages for</code>.</li>\n<li>Als Ergebnis (<code>«output»</code>) werden ein oder mehrere Bereitstellungsergebnisse an den <code>Back-end Server</code> übergeben (<code>1..*</code>), wo sie für Rollout, Update-Kampagnen oder Backend-Dienste persistiert und orchestriert werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodik definiert verbindliche Prozessschritte zur Handhabung von Adaptive Software Packages. Entwickler und Integratoren müssen beachten, dass Software-Pakete als standardisierte Übergabeeinheiten (Input) fungieren, welche im Backend-Server registriert und bereitgestellt werden. Die Rolle des OEM/ECU Software Managers trägt die Verantwortung für die Paketierungs- und Verwaltungsprozesse, bevor Pakete über Backend-Mechanismen (z. B. UCM / OTA) an Zielsteuergeräte verteilt werden.</p>"}, {"id": "FIG-5598fa23602ee1f7", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0- / UML-Aktivitätendiagramm zur Darstellung des methodischen Workflows für die Bereitstellung und Verwaltung von Software-Paketen im Kontext der AUTOSAR Adaptive Platform Methodology. Es veranschaulicht die organisatorische Einbettung von Rollen, Eingangs- und Ausgangs-Arbeitsergebnissen sowie die hierarchische Zerlegung von Aufgaben im Lebenszyklus der Software-Paketierung für Backend-Systeme.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen & Akteure</strong>:</li>\n<li><code>OEM</code>: Agierender Akteur, der über die Relation <code>«performs»</code> mit der Performer-Rolle <code>+ECU Software Manager</code> die Aktivität ausführt.</li>\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Provide and manage Software Packages</code>: Übergeordnete Aktivität.</li>\n<li><code>Management of Software Packages</code>: Verschachtelte Unteraktivität, angebunden über eine Aggregation mit Stereotyp <code>«nesting»</code>.</li>\n<li><code>Provision of Software Packages</code>: Verschachtelte Unteraktivität, angebunden über eine Aggregation mit Stereotyp <code>«nesting»</code>.</li>\n<li><strong>Arbeitsergebnisse (Work Products / Artefakte)</strong>:</li>\n<li><code>Software Package</code>: Eingangsartefakt (Stereotyp <code>«input»</code>, Multiplizität <code>1..*</code>).</li>\n<li><code>Back-end Server</code>: Ausgangskontext bzw. Zielartefakt (Stereotyp <code>«output»</code>, Multiplizität <code>1..*</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>OEM</code> agiert in der Rolle <code>+ECU Software Manager</code> und initiiert bzw. steuert den Ablauf <code>Provide and manage Software Packages</code> (<code>«performs»</code>).</li>\n<li>Mindestens ein <code>Software Package</code> (<code>1..*</code>) wird als Eingangsdaten (<code>«input»</code>) in die Aktivität eingebracht.</li>\n<li>Die Aktivität teilt sich über <code>«nesting»</code>-Beziehungen in die Unteraktivitäten <code>Management of Software Packages</code> und <code>Provision of Software Packages</code> auf.</li>\n<li>Als Prozessausgang (<code>«output»</code>) erfolgt die Übergabe an mindestens einen <code>Back-end Server</code> (<code>1..*</code>) zur weiteren Verteilung und Verwaltung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodik definiert verbindliche Prozessschritte zur Handhabung von Adaptive Software Packages. Entwickler und Integratoren müssen beachten, dass Software-Pakete als standardisierte Übergabeeinheiten (Input) fungieren, welche im Backend-Server registriert und bereitgestellt werden. Die Rolle des OEM/ECU Software Managers trägt die Verantwortung für die Paketierungs- und Verwaltungsprozesse, bevor Pakete über Backend-Mechanismen (z. B. UCM / OTA) an Zielsteuergeräte verteilt werden.</p>"}, {"id": "FIG-5ff3366d9c52de82", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0- / UML-Aktivitätendiagramm zur Darstellung des methodischen Workflows für die Bereitstellung und Verwaltung von Software-Paketen im Kontext der AUTOSAR Adaptive Platform Methodology. Es veranschaulicht die organisatorische Einbettung von Rollen, Eingangs- und Ausgangs-Arbeitsergebnissen sowie die hierarchische Zerlegung von Aufgaben im Lebenszyklus der Software-Paketierung für Backend-Systeme.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rollen & Akteure</strong>:</li>\n<li><code>OEM</code>: Agierender Akteur, der über die Relation <code>«performs»</code> mit der Performer-Rolle <code>+ECU Software Manager</code> die Aktivität ausführt.</li>\n<li><strong>Aktivitäten</strong>:</li>\n<li><code>Provide and manage Software Packages</code>: Übergeordnete Aktivität.</li>\n<li><code>Management of Software Packages</code>: Verschachtelte Unteraktivität, angebunden über eine Aggregation mit Stereotyp <code>«nesting»</code>.</li>\n<li><code>Provision of Software Packages</code>: Verschachtelte Unteraktivität, angebunden über eine Aggregation mit Stereotyp <code>«nesting»</code>.</li>\n<li><strong>Arbeitsergebnisse (Work Products / Artefakte)</strong>:</li>\n<li><code>Software Package</code>: Eingangsartefakt (Stereotyp <code>«input»</code>, Multiplizität <code>1..*</code>).</li>\n<li><code>Back-end Server</code>: Ausgangskontext bzw. Zielartefakt (Stereotyp <code>«output»</code>, Multiplizität <code>1..*</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>OEM</code> agiert in der Rolle <code>+ECU Software Manager</code> und initiiert bzw. steuert den Ablauf <code>Provide and manage Software Packages</code> (<code>«performs»</code>).</li>\n<li>Mindestens ein <code>Software Package</code> (<code>1..*</code>) wird als Eingangsdaten (<code>«input»</code>) in die Aktivität eingebracht.</li>\n<li>Die Aktivität teilt sich über <code>«nesting»</code>-Beziehungen in die Unteraktivitäten <code>Management of Software Packages</code> und <code>Provision of Software Packages</code> auf.</li>\n<li>Als Prozessausgang (<code>«output»</code>) erfolgt die Übergabe an mindestens einen <code>Back-end Server</code> (<code>1..*</code>) zur weiteren Verteilung und Verwaltung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Methodik definiert verbindliche Prozessschritte zur Handhabung von Adaptive Software Packages. Entwickler und Integratoren müssen beachten, dass Software-Pakete als standardisierte Übergabeeinheiten (Input) fungieren, welche im Backend-Server registriert und bereitgestellt werden. Die Rolle des OEM/ECU Software Managers trägt die Verantwortung für die Paketierungs- und Verwaltungsprozesse, bevor Pakete über Backend-Mechanismen (z. B. UCM / OTA) an Zielsteuergeräte verteilt werden.</p>"}], "trans": [{"from": "FIG-0d15c4f13ed62352", "to": "FIG-5598fa23602ee1f7", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Layout und Beschriftungsplatzierung: Die Beschriftung der Aktivität <code>Provide and manage Software Packages</code> wurde von rechts oberhalb der Aktivitätsbox nach direkt oberhalb der Box verschoben, wodurch das gesamte Diagrammlayout kompakter vertikal skaliert ist.</li>\n<li>Textabschneidung behoben: Die Beschriftung der verschachtelten Unteraktivität unten rechts lautet nun vollständig <code>Provision of Software Packages</code> (zuvor am rechten Bildrand als <code>Provision of Software Packages for</code> abgeschnitten).</li>\n<li>Positionierung der Kardinalitäten und Stereotypen: Die Multiplizität <code>1..*</code> an der Relation zu <code>Back-end Server</code> wurde unterhalb der Pfeillinie platziert.</li>\n</ul>"}, {"from": "FIG-5598fa23602ee1f7", "to": "FIG-5ff3366d9c52de82", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
